children.content:
terraform {
  required_version = ">= 1.6.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

locals {
  common_tags = {
    Project     = "Trak"
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

resource "aws_s3_bucket" "app_storage" {
  bucket_prefix = "trak-app-storage-"
  tags          = local.common_tags
}

variable "aws_region" {
  type        = string
  default     = "us-east-1"
  description = "Target AWS Region"
}

variable "environment" {
  type        = string
  default     = "production"
  description = "Deployment environment"
  validation {
    condition     = contains(["development", "staging", "production"], var.environment)
    error_message = "Environment must be development, staging, or production."
  }
}

output "bucket_arn" {
  value       = aws_s3_bucket.app_storage.arn
  description = "ARN of the provisioned S3 bucket"
}

terraform {
  required_version = ">= 1.6.0"
}

output "terraform_status" {
  value = "Terraform Core Engine Initialized Successfully"
}

terraform {
  required_version = ">= 1.5.0"
}

terraform {
  required_providers {
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

resource "random_pet" "server_name" {
  length = 2
}

output "generated_name" {
  value = random_pet.server_name.id
}

provider "aws" {
  alias  = "eu_central"
  region = "eu-central-1"
}

resource "random_id" "db_suffix" {
  byte_length = 4
  lifecycle {
    prevent_destroy = false
  }
}

lifecycle {
  ignore_changes = [
    tags,
  ]
}

variable "db_password" {
  type      = string
  sensitive = true
  default   = "SuperSecretPassword123!"
}

output "safe_status" {
  value = "Database credentials configured securely."
}

locals {
  tier = var.environment == "production" ? "premium" : "standard"
}

terraform {
  # Example Remote S3 Backend Configuration
  # backend "s3" {
  #   bucket         = "my-terraform-state-prod"
  #   key            = "global/s3/terraform.tfstate"
  #   region         = "us-east-1"
  #   dynamodb_table = "terraform-locks"
  #   encrypt        = true
  # }
}

terraform {
  backend "s3" {
    bucket  = "trak-state-bucket"
    key     = "prod/state.tfstate"
    region  = "us-east-1"
    encrypt = true
  }
}

