locals {
  subnets = toset(["subnet-a", "subnet-b", "subnet-c"])
}

resource "random_id" "subnet_ids" {
  for_each    = local.subnets
  byte_length = 2
}

output "all_subnet_hashes" {
  value = { for k, v in random_id.subnet_ids : k => v.hex }
}

locals {
  filtered = [for n in [4, 12, 8, 19] : n if n > 10]
}

variable "ingress_ports" {
  type    = list(number)
  default = [80, 443, 8080]
}

output "configured_ports" {
  value = var.ingress_ports
}

dynamic "ingress" {
  for_each = var.ingress_ports
  content {
    from_port = ingress.value
    to_port   = ingress.value
    protocol  = "tcp"
  }
}

# Example Module Invocation
module "storage" {
  source      = "./modules/s3_storage"
  bucket_name = "trak-reusable-module-bucket"
  environment = "production"
}

module "vpc" {
  source  = "git::https://github.com/terraform-aws-modules/terraform-aws-vpc.git?ref=v5.1.0"
}

